<script lang="ts">
 import SampleStageDialog from './SampleStageDialog.svelte';
 import SampleProcessPanel from './SampleProcessPanel.svelte';
 import SampleSpecImport from './SampleSpecImport.svelte';
 import {api} from './api';
 let {piece,data,merchant='',onchange,onprint,onform,onissue}:{piece:any;data:any;merchant?:string;onchange:()=>Promise<void>;onprint:(kind:string,id:number)=>void;onform:(kind:'indent'|'audit',id:number)=>void;onissue:()=>void}=$props();
 let busy=$state(false),error=$state(''),editor=$state(''),note=$state(''),audit:any=$state(null);
 async function action(action:string,extra:any={}){if(busy)return;busy=true;error='';try{await api('/sample-indents/'+piece.id,{version:piece.version,action,...extra});editor='';await onchange()}catch(e){error=(e as Error).message}finally{busy=false}}
 function startAudit(){error='';const previous=piece.production.audit_reports?.at(-1);audit={fabric_used:'Actual',trims_used:'Actual',style_used:'Actual',submission_attempt:String(Math.min(4,(previous?Number(previous.submission_attempt):0)+1)),special_remarks:'',merchant_contact:'',measurements:previous?structuredClone($state.snapshot(previous.measurements)):[]};note='';editor='audit'}
</script>
<article class="piece"><header><div><h3>#{piece.id}{#if piece.size} · {piece.size}{/if}{#if piece.colour} · {piece.colour}{/if}</h3><strong>{piece.status}</strong></div><div class="actions"><button class="button secondary" onclick={()=>onform('indent',piece.id)}>Sample Indent Form</button><button class="button secondary" onclick={()=>onform('audit',piece.id)}>Sample Audit Form</button>{#if piece.production.audit_reports?.length}<button class="button secondary" onclick={()=>onprint('audit',piece.id)}>Print audit reports</button>{/if}{#if piece.status==='Handed over'}<button class="button secondary" onclick={()=>onprint('dispatch',piece.id)}>Print dispatch label</button>{/if}</div></header>
 {#if error&&editor!=='audit'}<p class="form-error" role="alert">{error}</p>{/if}
 <SampleProcessPanel {piece} {merchant} {onchange} onaudit={startAudit}/>
 {#if data.can_stock&&!['Handed over','Rejected'].includes(piece.status)}<button class="button secondary" disabled={busy} onclick={onissue}>Issue fabric from stock</button>{/if}
 {#if editor==='audit'}<SampleStageDialog title={'Audit report · Indent #'+piece.id} close={()=>editor=''} {busy} wide><section class="editor">{#if error}<p class="form-error" role="alert">{error}</p>{/if}<p>Compare the required specification with the measured garment. Your account and submission time sign this report. The sample status changes after the report is reviewed.</p><div class="grid">{#each [['fabric_used','Fabric'],['trims_used','Trims'],['style_used','Style']] as [key,label]}<label>{label}<select bind:value={audit[key]}><option>Actual</option><option>Alternate</option></select></label>{/each}<label>Submission attempt<select bind:value={audit.submission_attempt}>{#each ['1','2','3','4'] as n}<option>{n}</option>{/each}</select></label><label>Special remarks<textarea bind:value={audit.special_remarks}></textarea></label><label>Merchant contact<input bind:value={audit.merchant_contact}/></label></div><h4>Measurements</h4><SampleSpecImport indent={piece.id} onsave={rows=>audit.measurements=rows}/>
 {#if !audit.measurements.length}<p>Add measurement points from the buyer specification.</p>{/if}
 {#each audit.measurements as row,i}<div class="measurement"><label>Measurement point<input bind:value={row.point}/></label><label>Required<input type="number" step="any" min="0" bind:value={row.required}/></label><label>Actual<input type="number" step="any" min="0" bind:value={row.actual}/></label><label>Unit<select bind:value={row.unit}><option>cm</option><option>mm</option><option>in</option></select></label><label>Tolerance ± (optional)<input type="number" step="any" min="0" bind:value={row.tolerance}/></label><label>Remarks<input bind:value={row.remarks}/></label><button class="text-button" onclick={()=>audit.measurements.splice(i,1)}>Remove</button></div>{/each}
 <button class="button secondary" disabled={audit.measurements.length>=100} onclick={()=>audit.measurements.push({point:'',required:'',actual:'',unit:'cm',tolerance:'',remarks:''})}>Add measurement</button><label class="remarks">QA decision remarks<textarea bind:value={note}></textarea></label><p>Upload the fabric swatch, trim card or audit attachment under Documents and select indent #{piece.id}.</p><footer>{#each ['Approved','Rework','Rejected'] as result}<button class="button secondary" disabled={busy||!audit.measurements.length||(result!=='Approved'&&!note.trim())} onclick={()=>action('audit',{result,note,audit})}>{result==='Approved'?'Submit QA approval':result==='Rework'?'Submit rework':'Submit rejection'}</button>{/each}<button class="text-button" disabled={busy} onclick={()=>editor=''}>Cancel</button></footer></section></SampleStageDialog>{/if}
 {#if piece.production.audit_reports?.length}<details><summary>Signed audit reports ({piece.production.audit_reports.length})</summary>{#each piece.production.audit_reports as report}<div class="audit-summary"><strong>Revision {report.revision} · {report.result}</strong><p>{report.auditor} · {new Date(report.signed_at).toLocaleString()} · Submission {report.submission_attempt}</p><div class="scroll"><table><thead><tr><th>Measurement</th><th>Required</th><th>Actual</th><th>Tolerance ±</th><th>Remarks</th></tr></thead><tbody>{#each report.measurements as m}<tr><td>{m.point}</td><td>{m.required} {m.unit}</td><td>{m.actual} {m.unit}</td><td>{m.tolerance||'—'}</td><td>{m.remarks}</td></tr>{/each}</tbody></table></div><p>{report.remarks} {report.special_remarks}</p></div>{/each}</details>{/if}
</article>
<style>
 @media(max-width:640px){.editor .grid,.measurement{grid-template-columns:repeat(2,minmax(0,1fr))}.measurement label:last-of-type{grid-column:1/-1}}
 .piece{color:#162638;font-weight:650;border:1px solid #dce3e9;background:#fff;padding:16px;border-radius:16px;margin:12px 0}.piece header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}h3{margin:4px 0 12px}p{line-height:1.55}.actions,footer{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}label{display:grid;gap:6px;color:#111;font-weight:600}input,select,textarea{width:100%;min-width:0;min-height:44px;padding:8px 10px;border:1px solid #cbd5df;border-radius:12px;background:#f8fafc;color:#111;font:inherit}textarea{resize:vertical}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 16px}.editor{min-width:0}.editor>p:first-of-type{margin-top:0}.measurement{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:12px;margin:12px 0;padding-bottom:12px;border-bottom:1px solid #dce3e9}.measurement label:last-of-type{grid-column:1/5}.remarks{margin-top:12px}summary{cursor:pointer;font-weight:600;margin:12px 0}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:8px;border-bottom:1px solid #dce3e9}.audit-summary{padding:12px;border:1px solid #dce3e9;border-radius:12px;margin:12px 0}
</style>
